"""El resto del Diccionario Strong, en español.

definiciones.py traduce a mano las entradas por orden de frecuencia, y
traducir_strong.py cubre las que siguen plantillas fijas. Quedaban 5085 que
ninguno de los dos alcanzaba —2537 griegas y 2548 hebreas—, y al tocar esas
palabras la ficha seguía mostrando el inglés de 1890. Aquí están todas,
traducidas a mano con los mismos criterios que definiciones.py: se traduce la
definición sin resumirla ni mejorarla, se conservan las marcas de registro
(«propiamente», «por implicación», «figuradamente») y las referencias a otros
números Strong, y los nombres propios van en la forma de la Reina-Valera.

Donde la entrada llegó cortada por el principio en la base, se traduce el
fragmento tal cual, sin reconstruir lo que falta. Donde la digitalización
convirtió la abreviatura «gen.» de Strong en «genitive case», que en esas
entradas quiere decir «generally», se traduce «en general».

Lo de definiciones.py manda sobre esto, y esto sobre lo automático.
"""

